class Solution:
    def removeAlmostEqualCharacters(self, word: str) -> int:
        n = len(word)
        INF = 10**9

        # dp[i][c] = min operations to process word[0..i] with word[i] set to character c
        dp = [[INF] * 26 for _ in range(n)]

        # Initialize for i = 0
        for c in range(26):
            dp[0][c] = 0 if ord(word[0]) - ord('a') == c else 1

        # Fill DP table
        for i in range(1, n):
            orig_idx = ord(word[i]) - ord('a')
            for c in range(26):
                cost_change = 0 if c == orig_idx else 1
                best = INF
                for p in range(26):
                    # Ensure not almost-equal: difference must be at least 2
                    if abs(p - c) >= 2:
                        if dp[i-1][p] + cost_change < best:
                            best = dp[i-1][p] + cost_change
                dp[i][c] = best

        return min(dp[n-1])
